  "implementation": "def solve(case):
    nodes = case['nodes']
    required_symbols = set(case['required_symbols'])
    # Build lookup
    nodes_by_id = {n['id']: n for n in nodes}
    children = {}
    for n in nodes:
        pid = n['parent']
        if pid is not None:
            children.setdefault(pid, []).append(n['id'])
    # Sort nodes: deeper first, then by id ascending
    sorted_nodes = sorted(nodes, key=lambda n: (-n['depth'], n['id']))
    removed = []
    removed_set = set()
    # Precompute symbol -> list of node ids
    symbol_to_ids = {}
    for n in nodes:
        sym = n['symbol']
        symbol_to_ids.setdefault(sym, []).append(n['id'])
    for current in sorted_nodes:
        cid = current['id']
        if cid in removed_set:
            continue
        if not current['removable']:
            continue
        if current['parent'] is None:
            continue  # root
        if current['symbol'] in required_symbols:
            continue
        # Check for retained children
        child_ids = children.get(cid, [])
        if any(child not in removed_set for child in child_ids):
            continue
        # Tentative removal: check required symbols
        # Temporarily consider cid as removed
        temp_removed = removed_set | {cid}
        ok = True
        for req_sym in required_symbols:
            ids_for_sym = symbol_to_ids.get(req_sym, [])
            # check if any id for this symbol is not in temp_removed
            if not any(i not in temp_removed for i in ids_for_sym):
                ok = False
                break
        if not ok:
            continue
        # Removal is valid
        removed.append(cid)
        removed_set.add(cid)
    retained = sorted(n['id'] for n in nodes if n['id'] not in removed_set)
    return {'removed_node_ids': removed, 'retained_node_ids': retained}"
}
